package com.trombokendu.chronos.analytics;import java.time.*;import java.util.random.*;public final class ShrunkModel implements SpendModel{private final SpendModel local,prior;private final double weight;public ShrunkModel(SpendModel l,SpendModel p,int n,double k){local=l;prior=p;weight=n/(n+k);}public double sampleDaily(RandomGenerator r,LocalDate d){return weight*local.sampleDaily(r,d)+(1-weight)*prior.sampleDaily(r,d);}}
